    "phrases": [
      {
        "id": "pb2-26-01",
        "vi": "A-lô. Đây là công ty du lịch Xuyên Việt.",
        "ru": "Здравствуйте, это туристическая компания «Сюен Вьет».",
        "start": 0.0,
        "end": 4.344989
      },
      {
        "id": "pb2-26-02",
        "vi": "Tôi và một người bạn muốn đi thăm Huế, Đà Lạt, Sài Gòn và Nha Trang.",
        "ru": "Мы с моей подругой хотели бы посетить Хюэ, Далат, Сайгон и Нячанг.",
        "start": 5.344989,
        "end": 11.529977
      },
      {
        "id": "pb2-26-03",
        "vi": "Xin chị chờ một lát. Vâng, xin chị cho biết quý danh.",
        "ru": "Подождите минутку, хорошо? Можно узнать ваше имя?",
        "start": 12.529977,
        "end": 18.994966
      },
      {
        "id": "pb2-26-04",
        "vi": "Trần Thị Thùy Dương.",
        "ru": "Чан Тхи Тхюи Зыонг.",
        "start": 19.994966,
        "end": 22.64898
      },
      {
        "id": "pb2-26-05",
        "vi": "Chị sẽ đi với ai?",
        "ru": "С кем вы путешествуете?",
        "start": 23.64898,
        "end": 25.731973
      },
      {
        "id": "pb2-26-06",
        "vi": "Với một người bạn tên là Angela Saroyan.",
        "ru": "Подругу зовут Анжела Сароян.",
        "start": 26.731973,
        "end": 29.729977
      },
      {
        "id": "pb2-26-07",
        "vi": "Khi nào hai chị muốn đi?",
        "ru": "Когда вы хотите поехать?",
        "start": 30.729977,
        "end": 33.22
      },
      {
        "id": "pb2-26-08",
        "vi": "Thứ hai tuần tới, ngày mười hai tháng này.",
        "ru": "В следующий понедельник, это будет 12-е число этого месяца.",
        "start": 34.22,
        "end": 37.869977
      },
      {
        "id": "pb2-26-09",
        "vi": "Hai chị muốn đi mấy tuần?",
        "ru": "На сколько недель?",
        "start": 38.869977,
        "end": 41.159955
      },
      {
        "id": "pb2-26-10",
        "vi": "Khoảng ba tuần.",
        "ru": "Где-то на 3 недели.",
        "start": 42.159955,
        "end": 43.832971
      },
      {
        "id": "pb2-26-11",
        "vi": "Hai chị muốn chúng tôi đón ở đâu?",
        "ru": "Куда за вами заехать?",
        "start": 44.832971,
        "end": 47.273968
      },
      {
        "id": "pb2-26-12",
        "vi": "Anh cho xe đến đón chúng tôi ở Khách sạn Hòa Bình, được không?",
        "ru": "Можете прислать автомобиль и забрать нас из отеля «Хоа Бинь»?",
        "start": 48.273968,
        "end": 53.329977
      },
      {
        "id": "pb2-26-13",
        "vi": "Dạ được. Hai chị muốn chúng tôi đến lúc mấy giờ sáng thứ hai?",
        "ru": "Конечно. В какое время подъехать в понедельник?",
        "start": 54.329977,
        "end": 59.823991
      },
      {
        "id": "pb2-26-14",
        "vi": "Khoảng tám giờ rưỡi.",
        "ru": "Около 8:30.",
        "start": 60.823991,
        "end": 62.52898
      }
    ]
