    "phrases": [
      {
        "id": "pb2-30-01",
        "vi": "Thưa bác, bác cho cháu hỏi chùa Một Cột ở đâu ạ?",
        "ru": "Дядюшка, не могли бы вы подсказать, как пройти к Пагоде на одной колонне?",
        "start": 0.0,
        "end": 4.861043
      },
      {
        "id": "pb2-30-02",
        "vi": "Cháu đi hết đường này đến đèn xanh đèn đỏ thì rẽ trái. Cháu đi thêm sáu dãy phố nữa rồi rẽ phải. Chùa ở ngay trước mặt.",
        "ru": "Идите по этой улице до светофора, затем поверните налево. Пройдите еще шесть кварталов, затем поверните направо. Пагода будет прямо перед вами.",
        "start": 5.861043,
        "end": 18.238005
      },
      {
        "id": "pb2-30-03",
        "vi": "Dạ, có xa lắm không, thưa bác?",
        "ru": "Это очень далеко отсюда?",
        "start": 19.238005,
        "end": 22.713016
      },
      {
        "id": "pb2-30-04",
        "vi": "Không xa lắm, nhưng cũng không gần. Bác nghĩ cháu không đi bộ được.",
        "ru": "Не очень, но и не очень близко. Я думаю, вы не доберетесь туда пешком.",
        "start": 23.713016,
        "end": 30.44
      },
      {
        "id": "pb2-30-05",
        "vi": "Cháu nên đi bằng gì ạ?",
        "ru": "Как же мне туда попасть в таком случае?",
        "start": 31.44,
        "end": 34.432018
      },
      {
        "id": "pb2-30-06",
        "vi": "Cháu có thể đi bằng xe xích-lô để ngắm đường phố Hà Nội.",
        "ru": "Вы можете воспользоваться услугами велорикши, чтобы полюбоваться улицами Ханоя.",
        "start": 35.432018,
        "end": 39.810023
      },
      {
        "id": "pb2-30-07",
        "vi": "Cháu đi bằng xe ôm được không ạ?",
        "ru": "Могу я взять мототакси?",
        "start": 40.810023,
        "end": 43.690023
      },
      {
        "id": "pb2-30-08",
        "vi": "Bác nghĩ đi bằng xe ôm không an toàn lắm.",
        "ru": "Я думаю, это небезопасно.",
        "start": 44.690023,
        "end": 48.129025
      },
      {
        "id": "pb2-30-09",
        "vi": "Cháu xin cám ơn bác rất nhiều. Chào bác ạ.",
        "ru": "Спасибо вам большое! До свидания!",
        "start": 49.129025,
        "end": 53.110023
      },
      {
        "id": "pb2-30-10",
        "vi": "Không có gì. Chào cháu.",
        "ru": "Пожалуйста. До свидания!",
        "start": 54.110023,
        "end": 56.739002
      }
    ]
