    "phrases": [
      {
        "id": "pb2-40-01",
        "vi": "Thành phố Huế đẹp quá!",
        "ru": "Хюэ так красив!",
        "start": 0.0,
        "end": 2.44
      },
      {
        "id": "pb2-40-02",
        "vi": "Đúng đấy. Bây giờ Angela có muốn chụp mấy bức ảnh không?",
        "ru": "Правда. Хочешь сделать несколько фотографий сейчас?",
        "start": 3.44,
        "end": 8.470023
      },
      {
        "id": "pb2-40-03",
        "vi": "Có chứ. Mình đứng ở đây chụp ảnh nhé. Từ chỗ này, chiếc cầu kia trông nho nhỏ mà lại xinh xinh.",
        "ru": "Конечно. Давай встанем здесь и сфотографируемся. Отсюда тот мост кажется очень маленьким и милым.",
        "start": 9.470023,
        "end": 17.66
      },
      {
        "id": "pb2-40-04",
        "vi": "Tiếng Việt của Angela giỏi lắm. Angela biết sử dụng cả từ láy nữa.",
        "ru": "Ты хорошо говоришь по-вьетнамски. Ты даже знаешь, как использовать удвоения.",
        "start": 18.66,
        "end": 24.88
      },
      {
        "id": "pb2-40-05",
        "vi": "Học ba mùa hè liên tục thì phải giỏi chứ.",
        "ru": "Если учишь язык три года, то будешь хорошо говорить.",
        "start": 25.88,
        "end": 28.86
      },
      {
        "id": "pb2-40-06",
        "vi": "Quên chưa hỏi Angela. Angela học tiếng Việt ở đâu vậy?",
        "ru": "Я забыла спросить тебя: где ты учила вьетнамский?",
        "start": 29.86,
        "end": 34.909977
      },
      {
        "id": "pb2-40-07",
        "vi": "Angela tham dự một chương trình mùa hè ở Mỹ.",
        "ru": "На летней программе в Америке.",
        "start": 35.909977,
        "end": 39.490023
      },
      {
        "id": "pb2-40-08",
        "vi": "Chắc các thầy cô ở đó dạy giỏi lắm.",
        "ru": "Наверное, учителя там действительно хорошие.",
        "start": 40.490023,
        "end": 43.64
      },
      {
        "id": "pb2-40-09",
        "vi": "Dĩ nhiên rồi.",
        "ru": "Конечно.",
        "start": 44.64,
        "end": 45.92
      }
    ]
