    "phrases": [
      {
        "id": "pb2-48-01",
        "vi": "Xin giới thiệu với Angela, đây là anh Thái, bạn học cũ của Thùy Dương ở trung học.",
        "ru": "Анжела, хочу тебя познакомить со своим другом. Это Тхай — мой одноклассник.",
        "start": 0.0,
        "end": 7.36
      },
      {
        "id": "pb2-48-02",
        "vi": "Rất vui được gặp anh.",
        "ru": "Очень рада с тобой познакомиться.",
        "start": 8.36,
        "end": 10.66
      },
      {
        "id": "pb2-48-03",
        "vi": "Rất vui được gặp Angela. Angela là người nước nào?",
        "ru": "Я тоже. Кто ты по национальности, Анжела?",
        "start": 11.66,
        "end": 17.18
      },
      {
        "id": "pb2-48-04",
        "vi": "Angela là người Mỹ.",
        "ru": "Я американка.",
        "start": 18.18,
        "end": 20.72
      },
      {
        "id": "pb2-48-05",
        "vi": "Angela sinh ra và lớn lên ở đâu trong nước Mỹ?",
        "ru": "Где именно в Америке ты родилась и росла?",
        "start": 21.72,
        "end": 26.490023
      },
      {
        "id": "pb2-48-06",
        "vi": "Angela sinh ra ở thành phố Madison, tiểu bang Wisconsin, nhưng lớn lên ở Quận Cam, tiểu bang Ca-li.",
        "ru": "Я родилась в городе Медисон, штат Висконсин. Росла в округе Ориндж-Каунти, штат Калифорния.",
        "start": 27.490023,
        "end": 37.726984
      },
      {
        "id": "pb2-48-07",
        "vi": "Tôi nghe nói ở đó có Sài Gòn Nhỏ, với mấy trăm ngàn người Mỹ gốc Việt, phải không?",
        "ru": "Я слышал, что там есть Маленький Сайгон с тысячами вьетнамских американцев, верно?",
        "start": 38.726984,
        "end": 45.88
      },
      {
        "id": "pb2-48-08",
        "vi": "Phải. Và đi đâu anh Thái cũng thấy bảng hiệu bằng tiếng Việt và nghe nhiều người nói tiếng Việt.",
        "ru": "Верно. Повсюду можно увидеть вывески на вьетнамском и услышать вьетнамскую речь.",
        "start": 46.88,
        "end": 54.749977
      },
      {
        "id": "pb2-48-09",
        "vi": "Thảo nào Angela nói tiếng Việt giỏi quá. À này, Angela và Thùy Dương gặp nhau ở đâu vậy?",
        "ru": "Неудивительно, что ты говоришь на вьетнамском так хорошо. Где ты и Тхюи Зыонг познакомились?",
        "start": 55.749977,
        "end": 65.170023
      },
      {
        "id": "pb2-48-10",
        "vi": "Thùy Dương đi du học ở Mỹ và gặp Angela ở một đại học.",
        "ru": "Я училась за границей в Америке и познакомилась с Анжелой в университете.",
        "start": 66.170023,
        "end": 72.36
      },
      {
        "id": "pb2-48-11",
        "vi": "Hóa ra vậy. Thùy Dương học ngành gì?",
        "ru": "Правда? Какая у тебя была специальность, Тхюи Зыонг?",
        "start": 73.36,
        "end": 77.14
      },
      {
        "id": "pb2-48-12",
        "vi": "Kinh doanh.",
        "ru": "«Бизнес».",
        "start": 78.14,
        "end": 79.54
      },
      {
        "id": "pb2-48-13",
        "vi": "Còn Angela?",
        "ru": "А твоя, Анжела?",
        "start": 80.54,
        "end": 82.029977
      },
      {
        "id": "pb2-48-14",
        "vi": "Kinh tế. Angela gặp Thùy Dương khi đang là sinh viên năm thứ ba.",
        "ru": "«Экономика». Я познакомилась с Тхюи Зыонг, когда была студенткой 3 курса.",
        "start": 83.029977,
        "end": 88.68
      }
    ]
