    "phrases": [
      {
        "id": "pb2-49-01",
        "vi": "Angela có những thú vui nào? Angela thường thích làm gì khi rảnh?",
        "ru": "Анжела, какое у тебя хобби? Чем ты обычно занимаешься в свободное время?",
        "start": 0.0,
        "end": 6.1
      },
      {
        "id": "pb2-49-02",
        "vi": "Angela thường đọc sách và nghe nhạc, thỉnh thoảng đi làm việc tình nguyện tại các bệnh viện hoặc trong cộng đồng. Còn anh Thái?",
        "ru": "Я обычно читаю книги, слушаю музыку. Иногда как волонтер работаю в больнице или в своей общине. А ты?",
        "start": 7.1,
        "end": 17.269977
      },
      {
        "id": "pb2-49-03",
        "vi": "Tôi chỉ thích ngủ. Nói đùa đấy. Thực sự thì tôi mê đá banh.",
        "ru": "Я люблю спать. Шучу. Вообще, я люблю играть в футбол.",
        "start": 18.269977,
        "end": 24.890023
      },
      {
        "id": "pb2-49-04",
        "vi": "Thùy Dương chỉ thích xem thôi. Nhất là khi có Cúp Thế Giới.",
        "ru": "А я больше люблю смотреть футбол. Особенно, если это Кубок мира.",
        "start": 25.890023,
        "end": 30.4
      },
      {
        "id": "pb2-49-05",
        "vi": "Cúp Thế Giới thì ai mà chẳng mê.",
        "ru": "Кто не любит Кубок мира!",
        "start": 31.4,
        "end": 36.569977
      },
      {
        "id": "pb2-49-06",
        "vi": "Thật không? Tôi tưởng người Mỹ mê banh bầu dục, bóng chày và quần vợt thôi.",
        "ru": "Правда? Я думал, американцы любят только регби, бейсбол и теннис.",
        "start": 37.569977,
        "end": 44.2
      },
      {
        "id": "pb2-49-07",
        "vi": "Có lẽ Thái nói đúng, nhưng chắc banh cà-na, dã cầu và bóng rổ là những môn thể thao được ưa chuộng nhất. Còn Thùy Dương?",
        "ru": "Возможно, ты прав, но, скорее, регби, бейсбол и баскетбол — наши любимые виды спорта. А как насчет тебя, Тхюи Зыонг?",
        "start": 45.2,
        "end": 55.530023
      },
      {
        "id": "pb2-49-08",
        "vi": "Thùy Dương rất mê đi bơi, rồi sau đó về nhà ngồi đọc một quyển tiểu thuyết hoặc nghe nhạc cổ điển, hoặc chơi vĩ cầm.",
        "ru": "Я люблю сначала поплавать, потом вернуться домой и почитать книгу или послушать классическую музыку, а может быть, даже поиграть на скрипке.",
        "start": 56.530023,
        "end": 67.04
      },
      {
        "id": "pb2-49-09",
        "vi": "Vậy Thùy Dương có biết đánh đàn dương cầm không?",
        "ru": "Ты вроде играешь на пианино?",
        "start": 68.04,
        "end": 72.22
      },
      {
        "id": "pb2-49-10",
        "vi": "Một chút thôi.",
        "ru": "Немного.",
        "start": 73.22,
        "end": 75.08
      }
    ]
