    "phrases": [
      {
        "id": "pb2-51-01",
        "vi": "Kế hoạch tuần sau của chúng mình như thế nào?",
        "ru": "Какие у нас планы на следующую неделю?",
        "start": 0.0,
        "end": 3.529977
      },
      {
        "id": "pb2-51-02",
        "vi": "Thứ hai mình sẽ đi tắm biển ở Vũng Tàu.",
        "ru": "В понедельник мы поедем в Вунгтау на море.",
        "start": 4.529977,
        "end": 8.689977
      },
      {
        "id": "pb2-51-03",
        "vi": "Mình có ngủ qua đêm ở đó không?",
        "ru": "Мы там останемся на ночь?",
        "start": 9.689977,
        "end": 12.68
      },
      {
        "id": "pb2-51-04",
        "vi": "Vũng Tàu chỉ cách Sài Gòn khoảng 100 cây số thôi. Sáng đi, tối về lại khách sạn, như vậy cho đỡ tốn tiền.",
        "ru": "Вунгтау находится всего лишь в 100 километрах от Сайгона. Мы выезжаем утром, а ночью вернемся в отель. Так мы сможем сэкономить.",
        "start": 13.68,
        "end": 24.3
      },
      {
        "id": "pb2-51-05",
        "vi": "Còn thứ ba mình đi đâu?",
        "ru": "И куда мы поедем во вторник?",
        "start": 25.3,
        "end": 27.849977
      },
      {
        "id": "pb2-51-06",
        "vi": "Đi thăm một vài thắng cảnh nào đó gần Sài Gòn.",
        "ru": "Посмотрим живописные места вокруг Сайгона.",
        "start": 28.849977,
        "end": 32.48
      },
      {
        "id": "pb2-51-07",
        "vi": "Và thứ tư mình đi chèo thuyền ở Đầm Sen, được không?",
        "ru": "А в среду мы поплаваем на каяках в Дам Сене?",
        "start": 33.48,
        "end": 38.969977
      },
      {
        "id": "pb2-51-08",
        "vi": "Được chứ. Còn thứ năm thì nghỉ xả hơi để thứ sáu đi thăm đồng bằng sông Cửu Long và phỏng vấn một vài người nông dân.",
        "ru": "Конечно. Тогда в четверг мы отдохнем, а в пятницу посмотрим дельту Меконга и сможем поговорить с крестьянами.",
        "start": 39.969977,
        "end": 50.729977
      },
      {
        "id": "pb2-51-09",
        "vi": "Đồng ý. Và bao giờ mình cần thuê xe?",
        "ru": "Отлично... Мы возьмем на прокат автомобиль?",
        "start": 51.729977,
        "end": 55.64
      },
      {
        "id": "pb2-51-10",
        "vi": "Lúc nào cũng có sẵn xe để thuê và cả tài xế nữa. Angela đừng lo.",
        "ru": "Арендовать автомобиль с шофером мы сможем в любое время. Не волнуйся!",
        "start": 56.64,
        "end": 62.92
      }
    ]
