    "phrases": [
      {
        "id": "pb2-54-01",
        "vi": "Nước biển ấm lắm. Hãy xuống bơi đi các bạn.",
        "ru": "Вода очень теплая, иди сюда, искупайся!",
        "start": 0.0,
        "end": 3.7
      },
      {
        "id": "pb2-54-02",
        "vi": "Angela muốn phơi nắng trước.",
        "ru": "Сначала я хочу позагорать.",
        "start": 4.7,
        "end": 7.249977
      },
      {
        "id": "pb2-54-03",
        "vi": "Cẩn thận nghe Thùy Dương. Đừng bơi ra xa, lỡ có sóng lớn.",
        "ru": "Аккуратнее, Тхюи Зыонг. Не заплывай слишком далеко, если волны большие.",
        "start": 8.249977,
        "end": 14.9
      },
      {
        "id": "pb2-54-04",
        "vi": "Cuộc sống ở đây thanh bình quá. Thế Nam may mắn thật.",
        "ru": "Здесь так спокойно. Тебе повезло, Тхе Нам.",
        "start": 15.9,
        "end": 21.44
      },
      {
        "id": "pb2-54-05",
        "vi": "Nhưng thanh niên thường muốn đi đây đi đó, chứ không muốn sống mãi ở một nơi.",
        "ru": "Молодежь всегда хочет куда-нибудь уехать, никто не хочет жить в одном месте.",
        "start": 22.44,
        "end": 28.64
      },
      {
        "id": "pb2-54-06",
        "vi": "Thế Nam muốn đi đâu?",
        "ru": "Куда бы ты хотел поехать?",
        "start": 29.64,
        "end": 31.82
      },
      {
        "id": "pb2-54-07",
        "vi": "Đi du học, rồi du lịch vòng quanh thế giới.",
        "ru": "Я хочу поехать учиться за границу, а потом путешествовать по миру.",
        "start": 32.82,
        "end": 37.36
      },
      {
        "id": "pb2-54-08",
        "vi": "Còn Angela chỉ muốn nằm ở đây, trên cát, ngắm trời xanh, mây trắng, những hòn đảo xa xa, những con chim hải âu và những chiếc thuyền đánh cá.",
        "ru": "А я бы только и лежала здесь на песке, глядя на голубое небо и белые облака, острова вдали, чаек и рыбацкие лодки.",
        "start": 38.36,
        "end": 52.709977
      },
      {
        "id": "pb2-54-09",
        "vi": "Angela trở thành thi sĩ rồi đó. Kìa, Thùy Dương đang ngoắc tay gọi mình xuống bơi kìa.",
        "ru": "Ты прямо поэт. Смотри, Тхюи Зыонг машет нам рукой, она зовет нас купаться.",
        "start": 53.709977,
        "end": 62.02
      },
      {
        "id": "pb2-54-10",
        "vi": "Nào thì bơi.",
        "ru": "Отлично, пойдем!",
        "start": 63.02,
        "end": 64.94
      }
    ]
